#!/usr/bin/env bash
set -euo pipefail

ROOT="${1:-${PROJECT_ROOT:-.}}"
APP="$ROOT/memeflow-app"
[[ -f "$APP/index.html" ]] || APP="$ROOT"
INDEX="$APP/index.html"

[[ -f "$INDEX" ]] || {
  echo "ERROR: index.html not found. Run this from ~/workspace."
  exit 1
}

PATCH_DIR="$APP/.memeflow-patches/mobile-chrome-clean-v5"
mkdir -p "$PATCH_DIR"

STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP="$PATCH_DIR/index.html.$STAMP.bak"
WORK="$PATCH_DIR/index.html.$STAMP.work"
PYTMP="$PATCH_DIR/mobile_chrome_v5_$STAMP.py"

cp "$INDEX" "$BACKUP"
cp "$INDEX" "$WORK"

rollback(){
  cp "$BACKUP" "$INDEX" 2>/dev/null || true
  rm -f "$WORK" "$PYTMP"
}

trap 'echo "ERROR: MOBILE CHROME CLEAN V5 failed; restoring exact pre-install index.html."; rollback' ERR

printf '%s' '' | base64 -d > "$PYTMP"
python3 "$PYTMP" "$WORK"

cp "$WORK" "$INDEX"
rm -f "$WORK" "$PYTMP"

cat > "$PATCH_DIR/latest-manifest.txt" <<EOF
INDEX=$INDEX
BACKUP=$BACKUP
EOF

trap - ERR

echo
echo "OK: MOBILE CHROME CLEAN V5 installed cleanly."
echo
echo "Header:"
echo "  - wallet tile: NONE"
echo "  - duplicate wallet status dot: NONE"
echo "  - wallet glyph: thin 23-24px line icon"
echo "  - click target: 42-44px"
echo
echo "Bottom navigation:"
echo "  - one CSS owner"
echo "  - compact floating dock: 60-62px"
echo "  - oversized Home tile removed"
echo "  - active item: subtle surface + 2px cyan/mint indicator"
echo "  - existing center AI control preserved"
echo
echo "Logic:"
echo "  - JS script bodies unchanged"
echo "  - navigation handlers unchanged"
echo "  - wallet logic unchanged"
echo "  - trading / AI / pre-trade unchanged"
echo
echo "Now Stop -> Run, then hard-refresh Safari."
